mapper.select:
SELECT ja.id AS application_id, ja.job_demand_id, jd.title AS job_title, ctry.name AS job_country, jd.city AS job_city, c.id AS candidate_id, CONCAT(c.first_name, ' ', c.last_name) AS candidate_name, c.trade AS candidate_trade, c.candidate_type, a.id AS agency_id, a.full_name AS agency_name, ja.status, ja.applied_at, ja.updated_at AS shortlisted_at, i.scheduled_at AS interview_scheduled_at, i.status AS interview_status FROM job_applications ja INNER JOIN job_demands jd ON ja.job_demand_id = jd.id INNER JOIN candidates c ON ja.candidate_id = c.id LEFT JOIN countries ctry ON jd.country_id = ctry.id LEFT JOIN users a ON c.agency_id = a.id LEFT JOIN interviews i ON ja.id = i.job_application_id WHERE ja.status = 'SHORTLISTED'
AND ja.job_demand_id = #{jobDemandId}
AND c.candidate_type = 'SELF_REGISTERED'
AND c.candidate_type = 'AGENCY_MANAGED'
ORDER BY ja.updated_at DESC LIMIT #{limit} OFFSET #{offset}
